using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
class AdapterTests {static int Main(string[] args){using(var a=AssemblyDefinition.ReadAssembly(args[0])){var m=a.MainModule.GetType("ShopOS.OsDesktop").Methods.Single(x=>x.Name=="DragTick");var ids=m.Body.Instructions.Where(i=>i.OpCode==OpCodes.Ldc_R4).Select(i=>DragMetricIds.Get((float)i.Operand)).Where(i=>i>=0).ToArray();var want=new[]{0,1,2,0,3,2,4,5,6,7,8,9,8,8,8};if(!ids.SequenceEqual(want))throw new Exception("Pinned DragTick metric mapping incomplete: "+String.Join(",",ids));Console.WriteLine("PASS pinned ShopOS DragTick: all 15 metrics, exact order");return 0;}}}
